using Microsoft.EntityFrameworkCore;
using PeopleHub.Infrastructure.Persistence;
using PeopleHub.Application.Services;
using PeopleHub.Domain.Entities;
namespace PeopleHub.Tests;
public class AdvanceBoundaryTests
{
 class User(int? emp=6,params string[] grants):ICurrentUser{public string Email=>"advanceboundary@example.local";public int? EmployeeId=>emp;public int UserId=>1;public bool IsAuthenticated=>true;public bool IsInRole(string r)=>false;public bool Can(string p)=>grants.Contains(p);}
 class Db(DbContextOptions options):AppDbContext(options){public bool Fail;public override async Task<int> SaveChangesAsync(CancellationToken ct=default){var n=await base.SaveChangesAsync(ct);if(Fail)throw new InvalidOperationException("Fictional post-write failure");return n;}}
 static async Task<Db> Open(){var d=new Db(new DbContextOptionsBuilder<AppDbContext>().UseSqlite("Data Source=:memory:").Options);await d.Database.OpenConnectionAsync();await d.Database.EnsureCreatedAsync();await SeedData.InitializeAsync(d,"Admin123!","Demo123!",new DateTime(2026,11,25));return d;}
 static ApprovalService S(AppDbContext d,User u){var c=new AppClock(TimeProvider.System);var a=new AuditService(d,u,c);return new(d,new AccessScope(d,u),u,a,new NotificationService(d,u,c),c,new WorkflowService(d,u,a),new DelegationService(d,u,a,c));}
 static async Task<int> Advance(AppDbContext d,int employeeId=6){var a=new AdvanceRequest{EmployeeId=employeeId,Amount=601.25m,Installments=3,StartYear=2030,StartMonth=1,Paid=100,Status=RequestStatus.Approved,Reason="Fictional boundary evidence",AttachmentToken="PRIVATE-TOKEN",AttachmentName="PRIVATE-FILE",Comment="PRIVATE-DECISION",Route="PRIVATE-ROUTE"};d.Add(a);await d.SaveAsync();return a.Id;}
 [Fact]public async Task AdvanceRowsAreDetachedMinimalAndCannotChangeTrackedProfiles(){await using var d=await Open();int id=await Advance(d);var e=(await d.Set<Employee>().FindAsync(6))!;e.Iban="PRIVATE-BANK";e.NationalId="PRIVATE-ID";e.Phone="PRIVATE-PHONE";e.Address="PRIVATE-ADDRESS";e.BasicSalary=12345;await d.SaveAsync();foreach(var user in new[]{new User(6),new User(7,Perm.ScopeCompany)}){var row=(await S(d,user).AdvancesAsync()).Single(x=>x.Id==id);Assert.NotSame(e,row.Employee);Assert.Equal(e.FullName,row.Employee.FullName);Assert.Equal(e.Code,row.Employee.Code);Assert.Equal("",row.Employee.Iban);Assert.Equal("",row.Employee.NationalId);Assert.Equal("",row.Employee.Phone);Assert.Equal("",row.Employee.Address);Assert.Equal(0,row.Employee.BasicSalary);Assert.Null(row.Employee.JobTitle);Assert.Null(row.Employee.Department);Assert.Null(row.Employee.Branch);Assert.Equal(200.42m,row.Monthly);Assert.Equal(501.25m,row.Remaining);Assert.DoesNotContain(typeof(AdvanceRow).GetProperties(),p=>p.Name is "AttachmentToken" or "AttachmentName" or "Comment" or "Route" or "WorkflowRevisionHash");row.Employee.FullName="Not persisted";}Assert.Equal("PRIVATE-BANK",e.Iban);Assert.Equal("PRIVATE-ID",e.NationalId);Assert.Equal(12345,e.BasicSalary);Assert.NotEqual("Not persisted",e.FullName);Assert.False(d.ChangeTracker.HasChanges());}
 [Fact]public async Task AdvanceRowsKeepEmployeeScopeAndUnlinkedUserSeesNothing(){await using var d=await Open();int own=await Advance(d),other=await Advance(d,7);var rows=await S(d,new User(6)).AdvancesAsync();Assert.Contains(rows,x=>x.Id==own);Assert.DoesNotContain(rows,x=>x.Id==other);Assert.Empty(await S(d,new User(null)).AdvancesAsync());Assert.Contains(await S(d,new User(null,Perm.ScopeCompany)).AdvancesAsync(),x=>x.Id==other);}
 [Fact]public async Task SettlementPostSaveFailureRollsBackBalanceAndAuditThenRetriesExactlyOnce(){await using var d=await Open();int id=await Advance(d);int audit=await d.Set<AuditLog>().CountAsync();d.Fail=true;await Assert.ThrowsAsync<InvalidOperationException>(()=>S(d,new User(8,Perm.AdvManage)).SettleAdvanceAsync(id));d.Fail=false;Assert.Equal(100,(await d.Set<AdvanceRequest>().FindAsync(id))!.Paid);Assert.Equal(audit,await d.Set<AuditLog>().CountAsync());Assert.False(d.ChangeTracker.HasChanges());await S(d,new User(8,Perm.AdvManage)).SettleAdvanceAsync(id);Assert.Equal(601.25m,(await d.Set<AdvanceRequest>().FindAsync(id))!.Paid);Assert.Single(await d.Set<AuditLog>().Where(x=>x.Entity=="Advance"&&x.Action=="Settle"&&x.EntityId==id.ToString()).ToListAsync());await Assert.ThrowsAsync<DomainException>(()=>S(d,new User(8,Perm.AdvManage)).SettleAdvanceAsync(id));Assert.Equal(audit+1,await d.Set<AuditLog>().CountAsync());}
 [Fact]public async Task SettlementOuterRollbackAndPermissionDenialLeaveBalancesUnchanged(){await using var d=await Open();int id=await Advance(d);int count=await d.Set<AuditLog>().CountAsync();await Assert.ThrowsAsync<DomainException>(()=>S(d,new User(8)).SettleAdvanceAsync(id));await Assert.ThrowsAsync<DomainException>(()=>d.AtomicAsync(async()=>{await S(d,new User(8,Perm.AdvManage)).SettleAdvanceAsync(id);throw new DomainException("Fictional outer failure");}));Assert.Equal(100,(await d.Set<AdvanceRequest>().FindAsync(id))!.Paid);Assert.Equal(count,await d.Set<AuditLog>().CountAsync());Assert.False(d.ChangeTracker.HasChanges());}
}
